css='''*{box-sizing:border-box}body{margin:0;background:#061e2f;color:#fff5de;font:16px/1.5 system-ui}main{max-width:1600px;margin:auto;padding:28px}h1{margin:12px 0}p{max-width:1050px}a{color:#f3cf7d}nav{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}.compare{display:grid;grid-template-columns:1fr 1fr;gap:18px}.compare img{width:100%;display:block}figure{margin:0}figcaption{padding:10px 0;font-size:14px}.devices,.screens{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:16px}.devices img{width:100%;height:350px;object-fit:contain;background:#0c344b}.screens{grid-template-columns:repeat(3,minmax(0,1fr))}.screen{display:flex;flex-direction:column;gap:10px;padding:12px;background:#0c344b;text-decoration:none;border:1px solid #82662c;border-radius:12px}.screen img{width:100%;height:380px;object-fit:contain}.screen span{color:#d9e8ec;font-size:14px}@media(max-width:700px){main{padding:16px}.devices,.screens{grid-template-columns:repeat(2,minmax(0,1fr))}}'''
